with incoming(lemma, kind, sense_id, ordinal, pos, gender, text, example, example_translation) as (values ('svigt', 'word', '72a3ede5-fe7a-5e5b-8bb5-24eea26b086b', 1, 'noun', 'et', 'failure, lapse', 'Ulykken skyldtes et svigt i systemet.', 'The accident was caused by a failure in the system.'), ('ydmyge', 'word', '278ac57e-5ff1-55be-9aab-45a30f4986b8', 1, 'verb', null, 'to humiliate', 'Han ville ikke ydmyge sin bror foran de andre.', 'He did not want to humiliate his brother in front of the others.'), ('diktere', 'word', 'b823f3f5-21c2-50ef-8710-bf1a6de7bace', 1, 'verb', null, 'to dictate', 'Chefen plejer at diktere breve til sin sekretær.', 'The boss usually dictates letters to his secretary.'), ('sulten', 'word', '67a1555c-935e-5f43-a7f7-15de0b668c7e', 1, 'adjective', null, 'hungry', 'Jeg er meget sulten efter turen.', 'I am very hungry after the trip.'), ('imperie', 'word', '1c0af3e5-f9d4-56dd-8cd4-072e95c7fc2d', 1, 'noun', null, 'empire', 'Det romerske imperie varede i mange århundreder.', 'The Roman empire lasted for many centuries.'), ('skænke', 'word', '6bdd4a4d-3b13-538c-b86d-d655e4908fd4', 1, 'verb', null, 'to pour (a drink)', 'Han skænker kaffe til gæsterne.', 'He pours coffee for the guests.'), ('skænke', 'word', '086ef1f4-fd67-59e6-9006-fc5b7dd2f7e5', 2, 'verb', null, 'to donate, to give', 'Familien valgte at skænke pengene til et hospital.', 'The family chose to donate the money to a hospital.'), ('socialist', 'word', '147d6e3c-d1f5-5d0c-ae19-5fd1727cd871', 1, 'noun', 'en', 'socialist', 'Han har altid kaldt sig socialist.', 'He has always called himself a socialist.'), ('ydmyg', 'word', '2495a746-d1b0-5935-9d2b-4011139c70a7', 1, 'adjective', null, 'humble', 'Han er ydmyg over for sin succes.', 'He is humble about his success.'), ('julemand', 'word', '890bbecb-a41a-5c2c-bd8b-cb3f18c26bd4', 1, 'noun', 'en', 'Father Christmas, Santa Claus', 'Børnene tror stadig på julemanden.', 'The children still believe in Santa Claus.'), ('blinke', 'word', '69e1bc6b-aa8