, null, 'pronounced, marked', 'Han har et udpræget talent for musik.', 'He has a pronounced talent for music.'), ('overnatte', 'word', 'a562098b-3765-5b0b-93dd-9daee53fc71c', 1, 'verb', null, 'to stay overnight', 'Vi skal overnatte hos vores venner.', 'We are going to stay overnight at our friends''.'), ('påføre', 'word', 'e74ddacf-feee-5f2c-9eb4-7a173483ec3c', 1, 'verb', null, 'to inflict, to cause (damage)', 'Stormen kan påføre store skader.', 'The storm can cause great damage.'), ('ocean', 'word', '2ff0a853-9293-5384-97f3-a57d43a7bcdc', 1, 'noun', 'et', 'ocean', 'Skibet sejlede over det store ocean.', 'The ship sailed across the great ocean.'), ('argumentation', 'word', 'c1116419-9d5c-5a0e-8153-17e05ab2c756', 1, 'noun', 'en', 'argumentation, reasoning', 'Hendes argumentation var meget overbevisende.', 'Her reasoning was very convincing.'), ('tolk', 'word', 'ce241457-63e9-5e64-84f7-fd748d80ae22', 1, 'noun', 'en', 'interpreter (spoken)', 'Vi havde brug for en tolk til mødet.', 'We needed an interpreter for the meeting.'), ('opad', 'word', '4f434453-5357-5a3a-8543-0b88412da76a', 1, 'adverb', null, 'upward', 'Trappen fører opad til taget.', 'The stairs lead upward to the roof.'), ('makker', 'word', '08f1d224-88d9-5d39-8666-9b4bfc017fa7', 1, 'noun', 'en', 'partner, mate', 'Han er min makker på arbejdet.', 'He is my mate at work.'), ('panel', 'word', 'b0a41d07-3721-53db-adff-3116e36ac78f', 1, 'noun', 'et', 'panel (of experts)', 'Et panel af eksperter diskuterede sagen.', 'A panel of experts discussed the matter.'), ('sauce', 'word', '296c7a42-218b-5c08-b35f-ba564fef4b8a', 1, 'noun', 'en', 'sauce', 'Kødet serveres med en lækker sauce.', 'The meat is served with a delicious sauce.'), ('hjemmekamp', 'word', 'b16197ed-8350-5e46-807b-6897608f20a6', 1, 'noun', 'en', 'home match', 'Klubben vandt sin hjemmekamp i går.', 'The club won its home match yesterday.'), ('fusionere', 'word', 'd17074a7-0fa0-5740-90d7-265f4441c75d', 1, 'verb', null, 'to merge (of companies)', 'De to fir